/**
 * @method
 * @name scwin.tx_Chk_Mkt_Holdy_calc
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_Chk_Mkt_Holdy_calc = async function () {
    const sbmOptions = {
        id: "tx_Chk_Mkt_Holdy_calc",
        method: "post",
