/**
 * @method
 * @name scwin.checkData
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkData = async function () {
    /* sdd-asis-lifecycle:begin fn_checkData — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.sendForm || { elements: [] });
    let currIsoCdCheckYn = false;
    for (let i = 0; i < 5; i++) {
        if ((String($c.util.getComponent(["ipt_currIsoCd", "ipt_currIsoCd2", "ipt_currIsoCd3", "ipt_currIsoCd4", "ipt_currIsoCd5"][i]).getValue() || '') !== '')) {
            currIsoCdCheckYn = true;
            break;
        }
    }
    if ($c.str.getByteLength($c.util.getComponent('dma_feeCalcReq').get('isurCd')) == 0) {
        await $c.win.alert("발행기관을 입력하십시오.");
        isurCd.focus();
        return false;
    } else {
        if (!currIsoCdCheckYn) {
            await $c.win.alert("발행통화를 입력하십시오.");
            console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return false;
        } else {
            if ($c.str.getByteLength($c.util.getComponent('ipt_listAmt').getValue()) == 0) {
                await $c.win.alert("상장예정금액을 입력하십시오.");
                $c.util.getComponent("ipt_listAmt").focus();
                return false;
            } else {
                if ($c.str.getByteLength($c.util.getComponent('cal_isuDd').getValue()) == 0) {
                    await $c.win.alert("발행일을 입력하십시오.");
                    $c.util.getComponent("ipt_listAmt").focus();
                    return false;
                } else {
                    if ($c.str.getByteLength($c.util.getComponent('cal_listDd').getValue()) == 0) {
                        await $c.win.alert("상장(예정)일을 입력하십시오.");
                        $c.util.getComponent("cal_listDd").focus();
                        return false;
                    } else {
                        if ($c.str.getByteLength($c.util.getComponent('cal_redmptDd').getValue()) == 0) {
                            await $c.win.alert("상환일을 입력하십시오.");
                            redmptDd.focus();
                            return false;
                        }
                    }
                }
            }
        }
    }
    await scwin.Chk_Mkt_Holdy_calc();
    if ($c.util.getComponent('ipt_temp').getValue() === 'Y') {
        await $c.win.alert("상장(예정)일을 매매일로 입력하십시오.");
        $c.util.getComponent("cal_listDd").focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


